-- Generated by check_mapping.py from mapping-data/examples/fraud-report-mapping.csv (postgres). Review before running.
-- Each query returns one row per check; a non-zero 'failing' value needs a look.

-- ===== fraud_report =====
-- 1. Row counts: source fraud_case_txn vs target fraud_report (the difference should match the rejection report)
SELECT (SELECT COUNT(*) FROM fraud_case_txn) AS source_rows, (SELECT COUNT(*) FROM fraud_report) AS target_rows;

-- 2. Key reconciliation on transaction_id (source fraud_case_txn.arn)
--    The key is transformed (TRIM(src.arn)): apply the same transformation to s.arn below.
SELECT 'missing in target' AS check_name, COUNT(*) AS failing FROM fraud_case_txn s
  WHERE NOT EXISTS (SELECT 1 FROM fraud_report t WHERE t.transaction_id = s.arn)
UNION ALL
SELECT 'not in source', COUNT(*) FROM fraud_report t
  WHERE NOT EXISTS (SELECT 1 FROM fraud_case_txn s WHERE s.arn = t.transaction_id)
UNION ALL
SELECT 'duplicate key in target', COUNT(*) - COUNT(DISTINCT transaction_id) FROM fraud_report;

-- 3. Data quality checks on fraud_report
SELECT check_name, rule, failing FROM (
  SELECT 'transaction_id mandatory' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN transaction_id IS NULL OR TRIM(CAST(transaction_id AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'transaction_id longer than 23' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN LENGTH(transaction_id) > 23 THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'pan_token mandatory' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN pan_token IS NULL OR TRIM(CAST(pan_token AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'pan_token longer than 19' AS check_name, 'DQ-02' AS rule, SUM(CASE WHEN LENGTH(pan_token) > 19 THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'fraud_type mandatory' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN fraud_type IS NULL OR TRIM(CAST(fraud_type AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'fraud_type longer than 2' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN LENGTH(fraud_type) > 2 THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'fraud_type not in allowed values' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN fraud_type IS NOT NULL AND fraud_type NOT IN ('0', '1', '2', '3', '4', '5', '6') THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'transaction_date mandatory' AS check_name, 'DQ-04' AS rule, SUM(CASE WHEN transaction_date IS NULL OR TRIM(CAST(transaction_date AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'fraud_reported_date mandatory' AS check_name, 'DQ-04' AS rule, SUM(CASE WHEN fraud_reported_date IS NULL OR TRIM(CAST(fraud_reported_date AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'amount_minor mandatory' AS check_name, 'DQ-05' AS rule, SUM(CASE WHEN amount_minor IS NULL OR TRIM(CAST(amount_minor AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'currency mandatory' AS check_name, 'DQ-05' AS rule, SUM(CASE WHEN currency IS NULL OR TRIM(CAST(currency AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'currency longer than 3' AS check_name, 'DQ-05' AS rule, SUM(CASE WHEN LENGTH(currency) > 3 THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'currency not in allowed values' AS check_name, 'DQ-05' AS rule, SUM(CASE WHEN currency IS NOT NULL AND currency NOT IN ('EUR', 'USD', 'GBP') THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'entry_mode longer than 12' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN LENGTH(entry_mode) > 12 THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'entry_mode not in allowed values' AS check_name, 'DQ-03' AS rule, SUM(CASE WHEN entry_mode IS NOT NULL AND entry_mode NOT IN ('CHIP', 'CONTACTLESS', 'ECOM', 'MAGSTRIPE', 'MANUAL') THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'case_id mandatory' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN case_id IS NULL OR TRIM(CAST(case_id AS VARCHAR(4000))) = '' THEN 1 ELSE 0 END) AS failing FROM fraud_report
UNION ALL
  SELECT 'case_id longer than 12' AS check_name, 'DQ-01' AS rule, SUM(CASE WHEN LENGTH(case_id) > 12 THEN 1 ELSE 0 END) AS failing FROM fraud_report
) c ORDER BY failing DESC;

